.stepper { display: inline-flex; align-items: center; gap: 4px; background: var(--surface-2); border: 1px solid var(--border); border-radius: 999px; padding: 3px; }
.stepper button { width: 30px; height: 30px; padding: 0 !important; display: grid; place-items: center; font-size: 1rem !important; }
.stepper span { padding: 0 8px; font-weight: 600; font-size: 0.85rem; }
.options { border: 1px solid var(--border); border-radius: var(--radius-sm); margin: 10px 0 0; padding: 4px 12px; background: var(--surface-2); }
.option { display: flex; align-items: center; gap: 12px; padding: 10px 0; cursor: pointer; }
.option + .option { border-top: 1px solid var(--border); }
.option .product { flex: 1; }
.option.selected .product-name { font-weight: 700; color: var(--brand-700); }
.search-again { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; margin-top: 10px; }
.search-again input { flex: 1 1 200px; }
.total-bar { position: sticky; bottom: 0; background: var(--surface); border-top: 1px solid var(--border); padding: 12px 0 4px; margin-top: 8px; z-index: 1; }
.total-row { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.total-row strong { font-size: 1.1rem; color: var(--brand-700); }

/* ---------- Build cart ---------- */
.approve { border: 2px solid var(--brand-100); background: linear-gradient(180deg, var(--brand-50), var(--surface) 70%); }
.approve h3 { font-size: 1.1rem; color: var(--brand-700); margin-bottom: 8px; }
.approve .actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; margin-top: 4px; }
.agree { display: flex; gap: 10px; align-items: flex-start; margin: 14px 0; padding: 12px; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-sm); cursor: pointer; }
.agree input { margin-top: 3px; width: 18px; height: 18px; flex: none; }
.cart-build h3 { color: var(--brand-700); font-size: 1.1rem; }
.build-head { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; margin-bottom: 6px; }
.live-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 14px; margin: 14px 0; }
.live-frame { display: flex; flex-direction: column; gap: 6px; }
.live-frame iframe, .live-placeholder { width: 100%; aspect-ratio: 16 / 10; border: 1px solid var(--border); border-radius: var(--radius); background: #0e1a13; box-shadow: var(--shadow); }
.live-placeholder { display: flex; align-items: center; justify-content: center; gap: 8px; color: #cfe8d8; font-size: 0.9rem; padding: 12px; text-align: center; background: radial-gradient(circle at 50% 40%, #1d3b2a, #0e1a13); }
.agent-action { display: flex; gap: 6px; font-size: 0.84rem; font-weight: 600; color: var(--brand-700); background: var(--brand-50); border: 1px solid var(--brand-100); padding: 7px 10px; border-radius: var(--radius-sm); overflow-wrap: anywhere; }
.outcomes { list-style: none; padding: 0; margin: 8px 0 0; }
.outcomes li { border-top: 1px solid var(--border); padding: 11px 0; }
.outcome-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.outcome-head .item-name { text-transform: capitalize; }
.build-done { margin-top: 14px; display: flex; flex-direction: column; gap: 10px; }
.build-done .actions { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.trust-row { list-style: none; padding: 0; margin: 0; display: flex; flex-wrap: wrap; gap: 8px 20px; color: var(--muted); font-size: 0.82rem; }
.trust-row li { display: inline-flex; align-items: center; gap: 6px; }
.trust-row .icon { color: var(--brand); }

/* ---------- Responsive ---------- */
@media (min-width: 1201px) {
  .total-bar { display: none; } /* the summary rail shows the total */
}
@media (max-width: 1200px) {
  .layout { grid-template-columns: 220px minmax(0, 1fr); }
  .summary { grid-column: 1 / -1; position: sticky; bottom: 0; top: auto; z-index: 15; margin: 0 -24px -24px; }
  .summary-inner { border-radius: 0; border-width: 1px 0 0; box-shadow: 0 -4px 16px rgba(16, 40, 24, 0.08); flex-direction: row; align-items: center; flex-wrap: wrap; gap: 12px 20px; padding: 12px 24px; }
  .summary-title, .summary-stats { display: none; }
  .summary .budget { flex: 1; min-width: 200px; }
  .summary-cta { width: auto; }
  .total-bar { display: none; } /* the summary bar shows the total */
}
@media (max-width: 860px) {
  .layout { grid-template-columns: minmax(0, 1fr); padding: 16px; gap: 16px; }
  .summary { margin: 0 -16px -16px; }
  .summary-inner { padding: 10px 16px; }
  .steps { position: sticky; top: var(--topbar-h); z-index: 10; margin: -16px -16px 0; background: rgba(245, 248, 245, 0.95); backdrop-filter: blur(6px); border-bottom: 1px solid var(--border); padding: 8px 16px; }
  .steps ol { flex-direction: row; gap: 6px; overflow-x: auto; scrollbar-width: none; }
  .steps ol::-webkit-scrollbar { display: none; }
  .step { padding: 6px 12px 6px 6px; gap: 8px; border-radius: 999px; border-color: var(--border); background: var(--surface); white-space: nowrap; width: auto; }
  .step-hint, .steps-foot { display: none; }
  .step-num { width: 24px; height: 24px; }
  .hero { grid-template-columns: 1fr; padding-top: 24px; }
  .hero-card { transform: none; }
  .features { grid-template-columns: 1fr; }
  .status-pill { max-width: 46vw; }
}
@media (max-width: 480px) {
  h1 { font-size: 1.35rem; }
  .card { padding: 16px; }
  .prices.card { padding: 4px 16px 12px; }
  .price-body, .price-item.pending { flex-direction: column; align-items: flex-start; }
  .line-cost { flex-direction: row; gap: 10px; align-items: baseline; }
  .option { align-items: flex-start; }
  .option .nowrap { white-space: normal; }
  .topbar { padding: 0 14px; }
  .status-pill { display: none; }
  .plan-request .plan-form .btn { width: 100%; }
  .summary .budget { min-width: 0; }
  .summary-cta { flex: 1; }
}

