export function Skeleton({ width = "100%", height = 14, className = "" }) {
  return <span className={`skeleton ${className}`} style={{ width, height }} aria-hidden="true" />;
}

const money = (x) => `$${(x ?? 0).toFixed(2)}`;

export function BudgetMeter({ total, budget, compact = false }) {
  const pct = budget ? Math.min(100, (total / budget) * 100) : 0;
  const over = total > budget;
  return (
    <div className={`budget ${over ? "over" : ""} ${compact ? "compact" : ""}`}>
      <div className="budget-nums">
        <strong>{money(total)}</strong>
        <span>{over ? `${money(total - budget)} over` : `${money(budget - total)} left`} of {money(budget)}</span>
      </div>
      <div className="budget-bar" role="meter" aria-valuemin={0} aria-valuemax={budget} aria-valuenow={total} aria-label="Cart total against budget">
        <span style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

export function Notice({ tone = "info", children }) {
  return (
    <div className={`notice notice-${tone}`} role={tone === "danger" ? "alert" : undefined}>
      <Icon name={tone === "danger" || tone === "warning" ? "alert" : "spark"} size={16} />
      <div>{children}</div>
    </div>
  );
}

export { money };
import ApproveCart from "../ApproveCart.jsx";
import CartBuild from "../CartBuild.jsx";
import { Icon, Notice } from "../ui.jsx";

/** Approve, watch the agent work live, and see what landed in the T&T cart. */
export default function BuildStep({ task, setTask, api, reload, goTo }) {
  const building = task.status === "building";
  const built = task.status === "built";
  const canApprove = task.status === "priced" || built;
  const cartRun = task.result?.cartRun;

  return (
    <div className="stack">
      <div className="page-head">
        <div>
          <h1>Build cart</h1>
          <p className="muted">
            {building
              ? "Autocart's agent is shopping on T&T for you. Watch it live below."
              : built
                ? "Your T&T cart is ready. Check out on T&T whenever you like."
                : "Approve once and Autocart's agent fills your real T&T cart. It never checks out or pays."}
          </p>
        </div>
      </div>

      {!canApprove && !building && (
        <Notice>
          Finish your cart first.{" "}
          <button type="button" className="link-btn" onClick={() => goTo("cart")}>Go to cart</button>
        </Notice>
      )}

      {task.error && !building && <Notice tone="warning">{task.error}</Notice>}

      {(building || built) && cartRun && (
        <CartBuild cartRun={cartRun} building={building} taskId={task.id} api={api} onUpdate={setTask} />
      )}

      {canApprove && !building && (
        <ApproveCart key={task.status} task={task} setTask={setTask} api={api} reload={reload} />
      )}

      <ul className="trust-row">
        <li><Icon name="shield" size={16} /> Agent access needs your one-time <strong>build cart</strong> permission</li>
        <li><Icon name="stop" size={16} /> Stop the agent any time</li>
        <li><Icon name="store" size={16} /> You check out on T&amp;T yourself</li>
      </ul>
    </div>
  );
}
import ReviewCart from "../ReviewCart.jsx";
import { Button, Card, Chip, Notice, Skeleton } from "../ui.jsx";

const fmtQty = (qs) => qs.map((q) => (q.unit === "count" ? `${q.amount}` : `${q.amount} ${q.unit}`)).join(" + ");
const fmtCategory = (c) => c.replace(/-/g, " & ");
const groupBy = (xs, key) => xs.reduce((acc, x) => ((acc[key(x)] ??= []).push(x), acc), {});

export default function CartStep({ task, setTask, api, refreshPrices, error, goTo }) {
  const researching = task.status === "researching";
  const building = task.status === "building";
  const research = task.result.research;
  const toBuy = task.result.toBuy ?? [];

  return (
    <div className="stack">
      <div className="page-head">
        <div>
          <h1>Your cart</h1>
          <p className="muted">
            {researching
              ? "Your list is ready. TinyFish is finding each item at T&T…"
              : "Swap products, change pack counts, or remove what you don't need. Nothing goes to T&T until you approve."}
          </p>
        </div>
        <div className="page-actions">
          {!researching && research && (
            <Button variant="ghost" icon="refresh" onClick={refreshPrices} disabled={building}>Refresh prices</Button>
          )}
          {task.status === "planned" && !research && (
            <Button icon="spark" onClick={refreshPrices}>Find prices on T&amp;T</Button>
          )}
        </div>
      </div>

      {error && <Notice tone="danger">{error}</Notice>}
      {task.error && !researching && <Notice tone="warning">{task.error}</Notice>}

      {researching && !research ? (
        <PricingList toBuy={toBuy} />
      ) : research ? (
        <>
          {researching && <Notice>Refreshing T&amp;T prices… your edits are kept where possible.</Notice>}
          <ReviewCart task={task} setTask={setTask} api={api} stale={researching || building} />
          {task.status === "priced" && (
            <div className="next-row">
              <Button icon="cart" onClick={() => goTo("build")}>Continue to build cart</Button>
            </div>
          )}
        </>
      ) : (
        <PricingList toBuy={toBuy} idle />
      )}
    </div>
  );
}

/** The shopping list straight after planning, with price slots filling in. */
function PricingList({ toBuy, idle = false }) {
  const byCategory = groupBy(toBuy, (i) => i.category);
  return (
    <Card>
      {Object.entries(byCategory).map(([cat, items]) => (
        <div key={cat} className="list-group">
          <h3 className="group-title">{fmtCategory(cat)}</h3>
          <ul className="price-list">
            {items.map((i) => (
              <li key={i.name} className="price-item pending">
                <div className="product">
                  <span className="img-placeholder skeleton" aria-hidden="true" />
                  <div>
                    <div className="item-name">{i.name}</div>
                    <div className="muted small">{fmtQty(i.quantities)} · used in {i.usedIn.length} meal{i.usedIn.length === 1 ? "" : "s"}</div>
                  </div>
                </div>
                <div className="line-cost">
                  {idle ? <Chip>Not priced yet</Chip> : (
                    <>
                      <Skeleton width={64} height={16} />
                      <span className="muted small">Finding T&amp;T price…</span>
                    </>
                  )}
                </div>
              </li>
            ))}
          </ul>
        </div>
      ))}
    </Card>
  );
}
import { useState } from "react";
import { Button, Card, Chip, Icon, Notice, Skeleton, money } from "../ui.jsx";

const SLOT_ORDER = { breakfast: 0, lunch: 1, dinner: 2 };
const groupBy = (xs, key) => xs.reduce((acc, x) => ((acc[key(x)] ??= []).push(x), acc), {});

export default function MealPlanStep({ task, startPlan, error, profileSaved, goTo }) {
