import { applyEdits, defaultSelections, summarize, optionsOf, MAX_PACKAGES } from "../server/review/cart.js";

const money = (x) => `$${x.toFixed(2)}`;
const fmtTime = (iso) => new Date(iso).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });

const STATUS = {
