/* ==========================================================================
   Autocart: paper, ink and one green. Receipt-style numbers.
   ========================================================================== */
:root {
  --bg: #f6f5f1;
  --surface: #ffffff;
  --surface-2: #faf9f6;
  --border: #e2e0d9;
  --border-strong: #cbc8bf;
  --text: #1c1e1b;
  --muted: #6b6e68;
  --brand: #11683a;
  --brand-600: #0d5a31;
  --brand-ink: #0d4a2a;
  --brand-tint: #eef4ef;
  --sale: #c2410c;
  --danger: #b42318;
  --danger-tint: #fcf1ef;
  --warning: #8a5300;
  --warning-tint: #fbf5e8;
  --radius: 6px;
  --radius-sm: 4px;
  --ring: 0 0 0 2px var(--bg), 0 0 0 4px var(--brand);
  --topbar-h: 56px;
  --sans: "IBM Plex Sans", system-ui, -apple-system, "Segoe UI", sans-serif;
  --mono: "IBM Plex Mono", ui-monospace, "SFMono-Regular", Menlo, monospace;
  color-scheme: light;
  font-family: var(--sans);
  color: var(--text);
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }
html, body { margin: 0; }
body { background: var(--bg); font-size: 15px; line-height: 1.5; }
h1, h2, h3, h4 { margin: 0; line-height: 1.2; color: var(--text); font-weight: 600; letter-spacing: -0.012em; }
h1 { font-size: 1.65rem; letter-spacing: -0.02em; }
h2 { font-size: 1.1rem; }
h3 { font-size: 0.98rem; }
p { margin: 0; }
a { color: var(--brand); text-underline-offset: 3px; }
img { max-width: 100%; }
strong { font-weight: 600; }
:focus-visible { outline: none; box-shadow: var(--ring); border-radius: var(--radius-sm); }

.muted { color: var(--muted); }
.small { font-size: 0.82rem; }
.lead { font-size: 1rem; color: var(--text); max-width: 70ch; }
.nowrap { white-space: nowrap; }
.num { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.stack { display: flex; flex-direction: column; gap: 20px; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }
.icon { flex: none; }
.error, .field-error { color: var(--danger); font-size: 0.85rem; }
.ok, .status-ok { color: var(--brand); display: inline-flex; align-items: center; gap: 4px; font-size: 0.85rem; font-weight: 500; }

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  font: inherit; font-weight: 500; font-size: 0.92rem; line-height: 1;
  padding: 10px 16px; border-radius: var(--radius-sm); border: 1px solid transparent;
  cursor: pointer; text-decoration: none; white-space: nowrap;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-primary { background: var(--brand); color: #fff; border-color: var(--brand); }
.btn-primary:hover:not(:disabled) { background: var(--brand-600); border-color: var(--brand-600); }
.btn-secondary { background: var(--surface); color: var(--text); border-color: var(--border-strong); }
.btn-secondary:hover:not(:disabled) { border-color: var(--text); }
.btn-ghost { background: transparent; color: var(--text); padding-left: 10px; padding-right: 10px; }
.btn-ghost:hover:not(:disabled) { background: rgba(28, 30, 27, 0.05); }
.btn-danger { background: var(--surface); color: var(--danger); border-color: var(--border-strong); }
.btn-danger:hover:not(:disabled) { border-color: var(--danger); }
.btn-lg { padding: 13px 22px; font-size: 1rem; }

/* Plain buttons inside older components (stepper, small actions). */
button:not(.btn):not(.link-btn):not(.step):not(.avatar):not(.menu-item) {
  font: inherit; font-weight: 500; font-size: 0.85rem; cursor: pointer;
  border-radius: var(--radius-sm); padding: 6px 12px; border: 1px solid var(--border-strong);
  background: var(--surface); color: var(--text);
}
button:not(.btn):not(.link-btn):not(.step):not(.avatar):not(.menu-item):hover:not(:disabled) { border-color: var(--text); }
button:disabled { opacity: 0.5; cursor: not-allowed; }
.link-btn {
  background: none; border: none; padding: 4px 0; font: inherit; font-weight: 500; font-size: 0.85rem;
  color: var(--brand); cursor: pointer; text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px;
}
.link-btn:hover:not(:disabled) { color: var(--brand-ink); text-decoration-thickness: 2px; }
.link-btn:disabled { color: var(--muted); text-decoration: none; }

/* ---------- Forms ---------- */
.field { display: flex; flex-direction: column; gap: 6px; min-width: 0; }
.field.grow { flex: 1; }
.field-label { font-weight: 500; font-size: 0.85rem; }
.field-hint { color: var(--muted); font-size: 0.78rem; }
input, select, textarea {
  font: inherit; color: var(--text); background: var(--surface);
  border: 1px solid var(--border-strong); border-radius: var(--radius-sm);
  padding: 9px 11px; width: 100%; min-width: 0;
  transition: border-color 0.12s;
}
input[type="number"] { font-family: var(--mono); }
input:hover, select:hover, textarea:hover { border-color: #a9a69c; }
input:focus, select:focus, textarea:focus { outline: none; border-color: var(--brand); box-shadow: 0 0 0 1px var(--brand); }
textarea { resize: vertical; }
input[type="checkbox"], input[type="radio"] { width: auto; accent-color: var(--brand); }
.form-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 16px; }
.form-grid.wide { grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); margin-top: 16px; }
.form-footer {
  display: flex; align-items: center; justify-content: space-between; gap: 12px; flex-wrap: wrap;
  position: sticky; bottom: 0; padding: 12px 0; background: var(--bg);
  border-top: 1px solid var(--border-strong);
}

/* ---------- Cards, labels, notices ---------- */
.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 20px; }
.card-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; margin: -2px 0 16px; padding-bottom: 12px; border-bottom: 1px solid var(--border); flex-wrap: wrap; }
.card-title { font-size: 1rem; }
.card-sub { color: var(--muted); font-size: 0.85rem; margin-top: 2px; }
.card-actions { display: flex; gap: 8px; }

/* Status labels: a coloured dot and text, square corners. */
.chip {
  display: inline-flex; align-items: center; gap: 6px; font-size: 0.76rem; font-weight: 500;
  padding: 2px 7px; border-radius: 3px; white-space: nowrap; border: 1px solid var(--border);
  background: var(--surface); color: var(--muted);
}
.chip::before { content: ""; width: 6px; height: 6px; border-radius: 50%; background: currentColor; flex: none; }
.chip:has(.spinner)::before, .chip:has(.icon)::before { display: none; }
.chip-mint, .chip-ok { color: var(--brand); }
.chip-warn { color: var(--warning); }
.chip-bad { color: var(--danger); }
.chip-muted, .chip-neutral { color: var(--muted); }
.chip-row { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; margin-top: 14px; }
.chip .spinner { width: 9px; height: 9px; border-width: 1.5px; }

.notice { display: flex; gap: 10px; align-items: flex-start; padding: 11px 14px; border-radius: 0 var(--radius-sm) var(--radius-sm) 0; font-size: 0.9rem; background: var(--surface); color: var(--text); border: 1px solid var(--border); border-left: 3px solid var(--brand); }
.notice .icon { margin-top: 2px; color: var(--brand); }
.notice-warning { border-left-color: var(--warning); background: var(--warning-tint); }
.notice-warning .icon { color: var(--warning); }
.notice-danger { border-left-color: var(--danger); background: var(--danger-tint); }
.notice-danger .icon { color: var(--danger); }
.card .notice { margin-top: 12px; }

.warnings { list-style: none; padding: 0; margin: 14px 0 0; display: grid; gap: 4px; }
.warnings li { font-size: 0.86rem; padding: 7px 12px; background: var(--surface-2); border-left: 3px solid var(--border-strong); }
.warnings .warn-allergy, .warnings .warn-diet, .warnings .warn-avoid, .warnings .warn-budget, .warnings .warn-not-found, .warnings .warn-fetch, .warnings .warn-no-link { border-left-color: var(--danger); background: var(--danger-tint); }
.warnings .warn-uncertain, .warnings .warn-long-list { border-left-color: var(--warning); background: var(--warning-tint); }
.warnings .warn-store-stock, .warnings .warn-allergy-check { border-left-color: var(--brand); }

.spinner-wrap { display: inline-flex; align-items: center; gap: 8px; color: var(--muted); font-size: 0.88rem; }
.spinner { display: inline-block; width: 13px; height: 13px; border: 1.5px solid var(--border-strong); border-top-color: var(--text); border-radius: 50%; animation: spin 0.8s linear infinite; vertical-align: -2px; }
@keyframes spin { to { transform: rotate(360deg); } }
.skeleton { display: block; border-radius: 3px; background: #eceae4; animation: fade 1.4s ease-in-out infinite alternate; }
@keyframes fade { from { opacity: 1; } to { opacity: 0.5; } }
.pulse, .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--brand); flex: none; }
.busy .dot { animation: blink 1.2s steps(2, start) infinite; }
@keyframes blink { to { visibility: hidden; } }
@media (prefers-reduced-motion: reduce) { .spinner, .skeleton, .busy .dot, .caret { animation: none; } }

/* ---------- Logo ---------- */
.logo { display: inline-flex; align-items: center; gap: 9px; color: var(--brand); }
.logo-mark { display: block; }
.logo-word { font-family: var(--mono); font-weight: 600; font-size: 1.05rem; color: var(--text); letter-spacing: -0.02em; }

/* ---------- App shell ---------- */
.boot { min-height: 100vh; display: grid; place-content: center; justify-items: center; gap: 16px; }
.boot.inline { min-height: 40vh; }
.app { min-height: 100vh; }
.topbar {
  position: sticky; top: 0; z-index: 20; height: var(--topbar-h);
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 0 24px; background: var(--surface); border-bottom: 1px solid var(--border);
}
.topbar-right { display: flex; align-items: center; gap: 16px; min-width: 0; }
.status-pill { display: inline-flex; align-items: center; gap: 8px; font-size: 0.82rem; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.status-pill.bad .dot { background: var(--danger); }
.menu { position: relative; }
.avatar { width: 32px; height: 32px; border-radius: 50%; border: 1px solid var(--border-strong); background: var(--surface-2); color: var(--text); font: inherit; font-weight: 600; font-size: 0.76rem; cursor: pointer; }
.avatar:hover { border-color: var(--text); }
.menu-pop { position: absolute; right: 0; top: 42px; min-width: 220px; background: var(--surface); border: 1px solid var(--border-strong); border-radius: var(--radius); box-shadow: 0 8px 24px rgba(28, 30, 27, 0.1); padding: 6px; z-index: 30; }
.menu-user { display: flex; flex-direction: column; padding: 8px 10px 10px; border-bottom: 1px solid var(--border); margin-bottom: 6px; overflow-wrap: anywhere; }
.menu-item { display: flex; align-items: center; gap: 8px; width: 100%; padding: 8px 10px; border: none; background: none; border-radius: var(--radius-sm); font: inherit; font-size: 0.9rem; color: var(--text); cursor: pointer; }
.menu-item:hover { background: var(--surface-2); }

.layout { display: grid; grid-template-columns: 210px minmax(0, 1fr) 290px; gap: 32px; max-width: 1360px; margin: 0 auto; padding: 32px 24px; align-items: start; }
.main { min-width: 0; display: flex; flex-direction: column; gap: 20px; }
.page-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; flex-wrap: wrap; }
.page-head p { margin-top: 6px; max-width: 68ch; }
.page-actions { display: flex; gap: 8px; }
.next-row { display: flex; justify-content: flex-end; }
.app-foot { padding: 24px 0 8px; border-top: 1px solid var(--border); margin-top: 12px; }

/* Step navigation: numbered list on desktop */
